    @Test void graphGetDoesNotWriteAndSubsetCannotPassAndLayoutIsSnapshotSafe()throws Exception{
        confirmForDraft();String c=createDraft(chen,chenAssignment).path("id").asText();var actor=identity.authenticate("Bearer "+chen);assertThatThrownBy(()->structures.graph(actor,"DRAFT",c,null)).isInstanceOf(com.argument.common.exception.BusinessException.class);assertThat(data.read("draft",c).path("graphId").isNull()).isTrue();element(chen,c,5,20,"GM-L");assertThat(validateDraft(chen,c).path("status").asText()).isEqualTo("INVALID");element(chen,c,20,39,"GM-L");assertThat(validateDraft(chen,c).path("status").asText()).isEqualTo("VALID");var d=data.read("draft",c);var partial=mapper.createObjectNode();partial.putArray("elementIds");partial.putArray("relationIds");assertThatThrownBy(()->structures.validate(actor,c,VersionJson.uuid(),d.path("recordVersion").asInt(),partial)).isInstanceOf(com.argument.common.exception.BusinessException.class);
        var b=mapper.createObjectNode().put("canvasWidth",1000).put("canvasHeight",800);var positions=b.putArray("nodePositions");int x=100;for(var id:d.path("elementIds"))positions.addObject().put("targetKind","ELEMENT").put("targetId",id.asText()).put("x",x+=200).put("y",200);String graphId=d.path("graphId").asText();String key=VersionJson.uuid();var saved=structures.saveLayout(actor,graphId,key,b);assertThat(structures.saveLayout(actor,graphId,key,b)).isEqualTo(saved);assertThat(data.find("layout","graphId",graphId)).hasSize(1);var v=versionService.submit(actor,c,VersionJson.uuid(),data.read("draft",c).path("recordVersion").asInt(),true,"");var snapshot=versions.snapshot(v.path("id").asText());assertThat(snapshot.path("layouts")).hasSize(1);for(var p:snapshot.path("layouts").get(0).path("nodePositions"))assertThat(p.path("targetId").asText()).isNotIn(d.path("elementIds").get(0).asText(),d.path("elementIds").get(1).asText());
    }
    String creator,chen,liu,arbiter,caseId,taskId,chenAssignment,liuAssignment;
    @BeforeEach void setup()throws Exception{
        clean();fixtures.run(null);accounts.run(null);creator=login("creator.li");chen=login("annotator.chen");liu=login("annotator.liu");arbiter=login("arbiter.zhao");
        var old=data.read("taskDocument","3cbb140f-0274-4871-8248-194271101a14");var command=mapper.createObjectNode().put("name","真实独立切割验收").put("guideVersionId",data.read("task",old.path("taskId").asText()).path("guideVersionId").asText()).put("taskType","FORMAL_RESEARCH").put("defaultRequiredAnnotators",2).put("autoPreannotationEnabled",false).put("expertConfirmationRequired",false).put("adjudicationReasonRequired",true);
        taskId=send("/api/v1/tasks",creator,VersionJson.uuid(),command,null,200).path("data").path("id").asText();
        var binding=mapper.createObjectNode().put("requiredAnnotators",2);for(String f:List.of("documentId","documentTextVersionId","annotationScopeId"))binding.set(f,old.get(f));
        caseId=send("/api/v1/tasks/"+taskId+"/documents",creator,VersionJson.uuid(),binding,null,200).path("data").path("id").asText();
        for(var token:List.of(chen,liu,arbiter))send("/api/v1/tasks/"+taskId+"/members",creator,VersionJson.uuid(),mapper.createObjectNode().put("userId",identity.authenticate("Bearer "+token).id()).put("memberRole",token.equals(arbiter)?"ARBITER":"ANNOTATOR"),null,200);
        var assignment=mapper.createObjectNode();var annotators=assignment.putArray("annotatorMemberIds");for(var m:data.find("member","taskId",taskId))if("ANNOTATOR".equals(m.path("memberRole").asText()))annotators.add(m.path("id").asText());else if("ARBITER".equals(m.path("memberRole").asText()))assignment.put("arbiterMemberId",m.path("id").asText());
        var r=mvc.perform(put("/api/v1/task-documents/"+caseId+"/assignments").header("Authorization","Bearer "+creator).header("Idempotency-Key",VersionJson.uuid()).header("If-Match",1).contentType("application/json").content(assignment.toString())).andReturn().getResponse();assertThat(r.getStatus()).as(r.getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).isEqualTo(200);
        send("/api/v1/tasks/"+taskId+"/transitions",creator,VersionJson.uuid(),mapper.createObjectNode().put("action","PUBLISH"),1,200);
        send("/api/v1/tasks/"+taskId+"/transitions",creator,VersionJson.uuid(),mapper.createObjectNode().put("action","START"),data.read("task",taskId).path("recordVersion").asInt(),200);
        for(var a:data.find("assignment","taskDocumentId",caseId))if(a.path("userId").asText().equals(identity.authenticate("Bearer "+chen).id()))chenAssignment=a.path("id").asText();else if(a.path("userId").asText().equals(identity.authenticate("Bearer "+liu).id()))liuAssignment=a.path("id").asText();
    }
    @AfterEach void after(){clean();}
    void clean(){for(String table:List.of("workflow_command_history","trial_correction_rounds","trial_segmentation_records","trial_downloads","trial_files","trial_data_events","trial_exports","trial_export_receipts","trial_final_commitments","trial_audit_events","final_review_transitions","final_annotation_versions","adjudication_transitions","adjudication_returned_versions","adjudication_decisions","adjudication_items","adjudication_sessions","annotation_mutation_receipts","snapshot_object_owners","annotation_version_snapshots","annotation_versions","annotation_case_counters","workflow_records"))jdbc.update("DELETE FROM "+table);}
    String login(String name)throws Exception{var r=mvc.perform(post("/api/v1/auth/login").contentType("application/json").content(mapper.createObjectNode().put("username",name).put("password","demo").toString())).andReturn().getResponse();assertThat(r.getStatus()).isEqualTo(200);return mapper.readTree(r.getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).path("data").path("token").asText();}
    ObjectNode send(String url,String token,String key,ObjectNode body,Integer version,int expected)throws Exception{var request=post(url).header("Authorization","Bearer "+token).header("Idempotency-Key",key).contentType("application/json").content(body.toString());if(version!=null)request.header("If-Match",version);var response=mvc.perform(request).andReturn().getResponse();assertThat(response.getStatus()).as(response.getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).isEqualTo(expected);return (ObjectNode)mapper.readTree(response.getContentAsString(java.nio.charset.StandardCharsets.UTF_8));}
    ObjectNode input(String assignment){var body=mapper.createObjectNode().put("assignmentId",assignment);body.putArray("boundaries").addObject().put("startOffset",5).put("endOffset",20);body.withArray("boundaries").addObject().put("startOffset",20).put("endOffset",39);return body;}
    String submit(String token,String assignment)throws Exception{send("/api/v1/task-documents/"+caseId+"/segmentation-submissions",token,VersionJson.uuid(),input(assignment),null,200);return data.find("segmentationSubmission","assignmentId",assignment).stream().max(Comparator.comparingInt(s->s.path("attemptNumber").asInt())).orElseThrow().path("id").asText();}
    void review(String id,String action)throws Exception{send("/api/v1/segmentation-submissions/"+id+"/reviews",arbiter,VersionJson.uuid(),mapper.createObjectNode().put("action",action).put("reviewReason","逐条检查原文与连续边界"),1,200);}
    ObjectNode calculate(){return trial.calculate(identity.authenticate("Bearer "+arbiter),caseId,VersionJson.uuid(),mapper.createObjectNode());}
    ObjectNode confirmation(ObjectNode calculation){var body=mapper.createObjectNode().put("calculationId",calculation.path("id").asText()).put("reason","已核对每人审核通过的完整独立输入");body.set("unifiedBoundaries",input(chenAssignment).get("boundaries"));return body;}


    ObjectNode confirmForDraft()throws Exception{String c=submit(chen,chenAssignment),l=submit(liu,liuAssignment);review(c,"ACCEPT");review(l,"ACCEPT");var calculation=calculate();return trial.confirm(identity.authenticate("Bearer "+arbiter),caseId,VersionJson.uuid(),confirmation(calculation));}
    ObjectNode createDraft(String token,String assignment)throws Exception{return send("/api/v1/task-documents/"+caseId+"/drafts",token,VersionJson.uuid(),mapper.createObjectNode().put("assignmentId",assignment),null,200).with("data").with("draft");}
    ObjectNode elementCommand(int start,int end,String label){return mapper.createObjectNode().put("startOffset",start).put("endOffset",end).put("labelCode",label);}
    ObjectNode element(String token,String id,int start,int end,String label)throws Exception{return send("/api/v1/annotation-drafts/"+id+"/elements",token,VersionJson.uuid(),elementCommand(start,end,label),null,200).with("data").with("element");}
    ObjectNode patchElement(String id,String token,String key,ObjectNode body,int version,int expected)throws Exception{var response=mvc.perform(patch("/api/v1/elements/"+id).header("Authorization","Bearer "+token).header("Idempotency-Key",key).header("If-Match",version).contentType("application/json").content(body.toString())).andReturn().getResponse();assertThat(response.getStatus()).as(response.getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).isEqualTo(expected);return (ObjectNode)mapper.readTree(response.getContentAsString(java.nio.charset.StandardCharsets.UTF_8));}
    void insert(String kind,ObjectNode row){jdbc.update("INSERT INTO workflow_records VALUES(?,?,?)",kind,row.path("id").asText(),row.toString());}
    @Test void onlyExplicitCreateAfterUniqueConfirmedCheckpointAndNoDefaultElements()throws Exception{
        String path="/api/v1/task-documents/"+caseId+"/drafts";var command=mapper.createObjectNode().put("assignmentId",chenAssignment);send(path,chen,VersionJson.uuid(),command,null,409);
        assertThat(mvc.perform(get("/api/v1/task-documents/"+caseId+"/my-draft").header("Authorization","Bearer "+chen)).andReturn().getResponse().getStatus()).isEqualTo(404);assertThat(data.find("draft","taskDocumentId",caseId)).isEmpty();
        var cp=confirmForDraft();String key=VersionJson.uuid();var created=send(path,chen,key,command,null,200);assertThat(created.path("data").path("segmentationCheckpoint").has("calculationId")).isFalse();assertThat(created.path("data").path("segmentationCheckpoint").has("reason")).isFalse();assertThat(created.path("data").path("segmentationCheckpoint").has("textSha256")).isFalse();var d=created.path("data").path("draft");assertThat(d.path("revision").asInt()).isEqualTo(1);assertThat(d.path("recordVersion").asInt()).isEqualTo(1);assertThat(d.path("elementIds")).isEmpty();assertThat(d.path("graphId").isNull()).isTrue();assertThat(d.path("segmentationCheckpointId")).isEqualTo(cp.get("id"));assertThat(send(path,chen,key,command,null,200).path("data")).isEqualTo(created.path("data"));send(path,chen,VersionJson.uuid(),command,null,409);assertThat(data.find("draft","taskDocumentId",caseId)).hasSize(1);
    }
    @Test void twoRealAccountsHaveDifferentDraftsAndBlindElementWrites()throws Exception{confirmForDraft();var c=createDraft(chen,chenAssignment);var l=createDraft(liu,liuAssignment);assertThat(c.get("id")).isNotEqualTo(l.get("id"));element(chen,c.path("id").asText(),5,20,"SF");assertThat(drafts.elements(identity.authenticate("Bearer "+liu),l.path("id").asText(),null,null).path("items")).isEmpty();send("/api/v1/annotation-drafts/"+c.path("id").asText()+"/elements",liu,VersionJson.uuid(),elementCommand(20,39,"SF"),null,403);assertThat(mvc.perform(get("/api/v1/annotation-drafts/"+c.path("id").asText()+"/elements").header("Authorization","Bearer "+arbiter)).andReturn().getResponse().getStatus()).isEqualTo(403);}
    @Test void classificationDerivesTextAndStableIdsAndRenumbersInTextOrder()throws Exception{confirmForDraft();String id=createDraft(chen,chenAssignment).path("id").asText();var second=element(chen,id,20,39,"SF");var first=element(chen,id,5,20,"GM-L");assertThat(first.path("displayNo").asText()).isEqualTo("P1");assertThat(data.read("element",second.path("id").asText()).path("displayNo").asText()).isEqualTo("P2");assertThat(first.path("text").asText()).isEqualTo(data.read("text",first.path("documentTextVersionId").asText()).path("normalizedText").asText().substring(5,20));var changed=patchElement(first.path("id").asText(),chen,VersionJson.uuid(),mapper.createObjectNode().put("labelCode","IS"),1,200).path("data").path("element");assertThat(changed.get("id")).isEqualTo(first.get("id"));assertThat(changed.path("displayNo").isNull()).isTrue();assertThat(changed.path("isProposition").asBoolean()).isFalse();assertThat(data.read("element",second.path("id").asText()).path("displayNo").asText()).isEqualTo("P1");assertThat(data.read("draft",id).path("revision").asInt()).isEqualTo(4);send("/api/v1/annotation-drafts/"+id+"/elements",chen,VersionJson.uuid(),elementCommand(5,20,"SF"),null,409);}
    @Test void patchCannotDropCollectionsOrForgeDerivedFieldsOrMoveBoundaries()throws Exception{confirmForDraft();String id=createDraft(chen,chenAssignment).path("id").asText();var e=element(chen,id,5,20,"SF");send("/api/v1/annotation-drafts/"+id+"/elements",chen,VersionJson.uuid(),elementCommand(20,39,"SF").put("displayNo","P99"),null,400);var body=mapper.createObjectNode();body.putArray("elementIds");var response=mvc.perform(patch("/api/v1/annotation-drafts/"+id).header("Authorization","Bearer "+chen).header("Idempotency-Key",VersionJson.uuid()).header("If-Match",2).contentType("application/json").content(body.toString())).andReturn().getResponse();assertThat(response.getStatus()).isEqualTo(409);assertThat(data.read("draft",id).path("elementIds")).hasSize(1);var moved=patchElement(e.path("id").asText(),chen,VersionJson.uuid(),mapper.createObjectNode().put("endOffset",19),1,423);assertThat(moved.path("error").path("details").get(0).path("boundaryChangeRequiresModel").asBoolean()).isTrue();patchElement(e.path("id").asText(),chen,VersionJson.uuid(),mapper.createObjectNode().put("labelCode","GM-C"),1,400);var stale=patchElement(e.path("id").asText(),chen,VersionJson.uuid(),mapper.createObjectNode().put("labelCode","IS"),2,409);assertThat(stale.path("error").path("details").get(0).path("currentRecordVersion").asInt()).isEqualTo(1);}
    @Test void deletionRestoresUnclassifiedBoundaryAndItsReceiptSurvivesTombstone()throws Exception{confirmForDraft();String id=createDraft(chen,chenAssignment).path("id").asText();var e=element(chen,id,5,20,"SF");String key=VersionJson.uuid();var body=mapper.createObjectNode().put("reason","重新分类该统一边界");for(int i=0;i<2;i++){var response=mvc.perform(delete("/api/v1/elements/"+e.path("id").asText()).header("Authorization","Bearer "+chen).header("Idempotency-Key",key).header("If-Match",1).contentType("application/json").content(body.toString())).andReturn().getResponse();assertThat(response.getStatus()).as(response.getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).isEqualTo(200);}assertThat(data.read("draft",id).path("elementIds")).isEmpty();assertThat(data.read("deletedElement",e.path("id").asText()).path("text")).isEqualTo(e.get("text"));assertThat(drafts.context(identity.authenticate("Bearer "+chen),caseId).path("elements")).isEmpty();}
    @Test void relationReferencesBlockDeletionAndCategoryChange()throws Exception{confirmForDraft();String id=createDraft(chen,chenAssignment).path("id").asText();var e=element(chen,id,5,20,"SF");var relation=mapper.createObjectNode();VersionJson.stamp(relation,identity.authenticate("Bearer "+chen).id(),VersionJson.now());relation.put("ownerType","DRAFT").put("ownerId",id).put("status","ACTIVE");insert("relation",relation);var participant=mapper.createObjectNode();VersionJson.stamp(participant,identity.authenticate("Bearer "+chen).id(),VersionJson.now());participant.set("relationId",relation.get("id"));participant.put("targetKind","ELEMENT").set("targetId",e.get("id"));insert("participant",participant);patchElement(e.path("id").asText(),chen,VersionJson.uuid(),mapper.createObjectNode().put("labelCode","IS"),1,409);var response=mvc.perform(delete("/api/v1/elements/"+e.path("id").asText()).header("Authorization","Bearer "+chen).header("Idempotency-Key",VersionJson.uuid()).header("If-Match",1).contentType("application/json").content(mapper.createObjectNode().put("reason","测试引用保护").toString())).andReturn().getResponse();assertThat(response.getStatus()).isEqualTo(409);assertThat(data.read("element",e.path("id").asText()).path("isProposition").asBoolean()).isTrue();}
    @Test void elementEditInvalidatesExistingGraphAndGraphReferencePreventsDeletion()throws Exception{
        confirmForDraft();String id=createDraft(chen,chenAssignment).path("id").asText();var e=element(chen,id,5,20,"SF");var graph=mapper.createObjectNode();var actor=identity.authenticate("Bearer "+chen);VersionJson.stamp(graph,actor.id(),VersionJson.now());graph.put("ownerType","DRAFT").put("ownerId",id).put("status","VALID");graph.putArray("elementIds").add(e.path("id").asText());insert("graph",graph);var d=data.read("draft",id);d.set("graphId",graph.get("id"));data.replace("draft",d);
        patchElement(e.path("id").asText(),chen,VersionJson.uuid(),mapper.createObjectNode().put("labelCode","GM-L"),1,200);assertThat(data.read("graph",graph.path("id").asText()).path("status").asText()).isEqualTo("INVALID");
        var response=mvc.perform(delete("/api/v1/elements/"+e.path("id").asText()).header("Authorization","Bearer "+chen).header("Idempotency-Key",VersionJson.uuid()).header("If-Match",2).contentType("application/json").content("{\"reason\":\"check graph reference\"}")).andReturn().getResponse();assertThat(response.getStatus()).isEqualTo(409);assertThat(mapper.readTree(response.getContentAsByteArray()).path("error").path("code").asText()).isEqualTo("GRAPH_REFERENCES_ELEMENT");assertThat(data.read("draft",id).path("elementIds")).hasSize(1);
    }
    @Test void phaseOnlySavePreservesEntitiesAndReplaysBeforeVersionCheck()throws Exception{
        confirmForDraft();String id=createDraft(chen,chenAssignment).path("id").asText();element(chen,id,5,20,"SF");var actor=identity.authenticate("Bearer "+chen);var before=data.read("draft",id);String key=VersionJson.uuid();var command=mapper.createObjectNode().put("phase","ELEMENTS");var result=drafts.save(actor,id,key,2,command);assertThat(result.path("elementIds")).isEqualTo(before.path("elementIds"));assertThat(result.path("recordVersion").asInt()).isEqualTo(3);assertThat(drafts.save(actor,id,key,2,command)).isEqualTo(result);assertThatThrownBy(()->drafts.save(actor,id,VersionJson.uuid(),2,command)).isInstanceOf(VersionFailure.class);assertThat(data.read("draft",id)).isEqualTo(result);
    }
    @Test void concurrentCreationSerializesOnTheSameCase()throws Exception{confirmForDraft();var actor=identity.authenticate("Bearer "+chen);var body=mapper.createObjectNode().put("assignmentId",chenAssignment);var executor=java.util.concurrent.Executors.newFixedThreadPool(2);try{var futures=executor.invokeAll(List.of((java.util.concurrent.Callable<Boolean>)()->{try{drafts.create(actor,caseId,VersionJson.uuid(),body);return true;}catch(com.argument.common.exception.BusinessException e){assertThat(e.getErrorCode()).isEqualTo(com.argument.common.exception.ErrorCode.ACTIVE_DRAFT_EXISTS);return false;}},()->{try{drafts.create(actor,caseId,VersionJson.uuid(),body);return true;}catch(com.argument.common.exception.BusinessException e){assertThat(e.getErrorCode()).isEqualTo(com.argument.common.exception.ErrorCode.ACTIVE_DRAFT_EXISTS);return false;}}));assertThat(List.of(futures.get(0).get(),futures.get(1).get())).containsExactlyInAnyOrder(true,false);assertThat(data.find("draft","taskDocumentId",caseId)).hasSize(1);}finally{executor.shutdownNow();}}
    @Test void submittedFrozenSourceRemainsReadableAndCannotBeEdited()throws Exception{String id="f67848e1-a06d-4600-8454-19055e720d2c";var actor=identity.authenticate("Bearer "+chen);var version=versionService.submit(actor,id,VersionJson.uuid(),1,true,"");String snapshot=versionService.read(actor,version.path("id").asText()).toString();String element=data.read("draft",id).path("elementIds").get(0).asText();patchElement(element,chen,VersionJson.uuid(),mapper.createObjectNode().put("labelCode","IS"),data.read("element",element).path("recordVersion").asInt(),423);assertThat(versionService.read(actor,version.path("id").asText()).toString()).isEqualTo(snapshot);}
